@push('include-css')
<style>
.po-page{background:#f5f8fa;min-height:calc(100vh - 66px);padding:20px 0 40px;color:#243746}.po-breadcrumb{font-size:12px;color:#758693;margin:0 0 14px}.po-breadcrumb span{padding:0 8px;color:#afbac1}.po-breadcrumb a{color:#167a73}.po-page-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:22px}.po-page-heading h1{font-size:27px;font-weight:650;color:#183b56;margin:0 0 6px}.po-page-heading p{margin:0;color:#74838c;font-size:13px}.po-eyebrow{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#0f766e;font-weight:700;margin-bottom:7px!important}.po-primary{background:#0f766e;border-color:#0f766e}.po-primary:hover,.po-primary:focus{background:#0b615b;border-color:#0b615b}.po-card{background:#fff;border:1px solid #e1e8ec;border-radius:7px;box-shadow:0 2px 8px rgba(24,59,86,.04);margin-bottom:17px;padding:0 20px 18px;min-width:0}.po-card-heading{display:flex;justify-content:space-between;align-items:center;gap:15px;border-bottom:1px solid #edf1f3;padding:17px 0 13px;margin-bottom:15px}.po-card-heading h2{font-size:15px;color:#183b56;font-weight:650;margin:0 0 4px}.po-card-heading span{font-size:11px;color:#84919a}.po-filter-card{padding-top:18px}.po-filters{display:grid;grid-template-columns:repeat(3,minmax(140px,1fr));gap:13px;align-items:end}.po-filters label,.po-form-grid label{display:block;font-size:11px;font-weight:600;color:#546672;margin:0}.po-filters .form-control,.po-form-grid .form-control,.po-line .form-control{border:1px solid #d8e1e6;border-radius:4px;box-shadow:none;color:#293d4b;font-size:13px;height:39px;margin-top:6px}.po-filter-actions{display:flex;gap:8px;align-items:center}.po-table{margin:0;color:#334653}.po-table th{font-size:10px;letter-spacing:.35px;text-transform:uppercase;color:#71818b;background:#fafcfc;border-bottom:1px solid #e7edef!important;white-space:nowrap}.po-table td{font-size:12px;vertical-align:middle!important}.po-table .text-right,.po-money{text-align:right;font-variant-numeric:tabular-nums}.po-number{font-weight:700;color:#14776f}.po-status{display:inline-flex;border-radius:20px;padding:5px 9px;font-size:10px;font-weight:700;white-space:nowrap}.po-status-draft{background:#fff4d9;color:#8a5a00}.po-status-approved{background:#e5f2ff;color:#245a91}.po-status-partially_received{background:#eee9ff;color:#5b46a3}.po-status-received{background:#e4f5ea;color:#227044}.po-status-cancelled{background:#fce8e7;color:#a13f38}.po-actions{white-space:nowrap}.po-empty{padding:38px 14px;display:flex;align-items:center;flex-direction:column;gap:9px;text-align:center;color:#788791}.po-empty strong{font-size:15px;color:#294453}.po-empty-icon{font-size:25px;color:#74aaa4}.po-pagination{padding-top:14px}.po-pagination nav{margin:0}.po-form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.po-form-grid em{color:#bf4b44;font-style:normal}.po-currency{height:39px;margin-top:6px;display:flex;align-items:center;justify-content:space-between;border:1px solid #d8e1e6;border-radius:4px;background:#f7f9fa;padding:0 11px;color:#294453}.po-form-grid small{display:block;color:#87949b;font-size:10px;margin-top:5px}.po-vendor-panel{margin-top:17px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;background:#f7fafb;border:1px solid #e4ecef;border-radius:5px;padding:13px;color:#80909a;font-size:12px}.po-vendor-panel div{min-width:0}.po-vendor-panel small,.po-vendor-panel strong{display:block}.po-vendor-panel small{color:#87959d;font-size:10px;margin-bottom:4px}.po-vendor-panel strong{color:#354b59;font-weight:600;overflow-wrap:anywhere}.po-lines-table{min-width:1050px}.po-lines-table td{min-width:70px}.po-lines-table td:first-child{min-width:185px}.po-lines-table td:nth-child(2){min-width:180px}.po-lines-table .form-control{min-width:75px}.po-lines-table .po-item-select{min-width:180px}.po-lines-table .po-description{min-width:160px}.po-reference{background:#f6f8f9!important}.po-line-total{font-variant-numeric:tabular-nums;white-space:nowrap}.po-totals{margin:15px 0 0 auto;max-width:340px}.po-totals>div{display:flex;justify-content:space-between;gap:20px;padding:7px 0;color:#647581;font-size:12px}.po-totals strong{font-variant-numeric:tabular-nums;color:#294453}.po-totals .po-grand-total{border-top:1px solid #dfe7ea;padding-top:12px;margin-top:4px;font-size:15px;color:#183b56}.po-grand-total strong{font-size:17px;color:#0f766e}.po-totals>small{display:block;color:#87959d;font-size:10px;text-align:right;margin-top:5px}.po-notes-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.po-notes-grid textarea{height:auto;min-height:85px}.po-form-actions,.po-heading-actions{display:flex;justify-content:flex-end;align-items:center;gap:9px}.po-errors{margin:8px 0 0;padding-left:19px}.po-summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:17px}.po-summary-card{background:#fff;border:1px solid #e1e8ec;border-radius:7px;padding:15px;min-width:0}.po-summary-card small,.po-summary-card strong,.po-summary-card span{display:block}.po-summary-card small{font-size:10px;color:#75848e;text-transform:uppercase;letter-spacing:.4px}.po-summary-card strong{font-size:16px;color:#183b56;margin:8px 0 3px;overflow-wrap:anywhere}.po-summary-card span{font-size:10px;color:#8a969e}.po-detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.po-details{margin:0}.po-details>div{display:grid;grid-template-columns:minmax(100px,.7fr) 1fr;gap:12px;padding:9px 0;border-bottom:1px solid #f0f3f4}.po-details>div:last-child{border-bottom:0}.po-details dt{font-size:11px;color:#788791;font-weight:500}.po-details dd{font-size:12px;color:#304652;font-weight:600;margin:0;overflow-wrap:anywhere}.po-notes-display{display:grid;grid-template-columns:1fr 1fr;gap:20px}.po-notes-display small{font-size:10px;text-transform:uppercase;color:#829099}.po-notes-display p{font-size:12px;white-space:pre-line;color:#354b59}.po-stage-note{font-size:11px;color:#617884;margin:0 0 12px}.po-stage-note i{color:#39877f}.text-danger{color:#b85048}
