@media(max-width:600px){.po-page{padding:14px 0 25px}.po-page-heading{align-items:flex-start;flex-direction:column}.po-page-heading h1{font-size:23px}.po-card{padding-left:13px;padding-right:13px}.po-card-heading{align-items:flex-start}.po-filters,.po-form-grid,.po-notes-grid,.po-detail-grid,.po-notes-display{grid-template-columns:1fr}.po-filter-actions{flex-wrap:wrap}.po-vendor-panel{grid-template-columns:repeat(2,minmax(0,1fr))}.po-summary-grid{grid-template-columns:1fr 1fr;gap:8px}.po-summary-card{padding:11px}.po-summary-card strong{font-size:14px}.po-form-actions{position:sticky;bottom:0;background:#f5f8fa;padding:10px 0;z-index:2}.po-heading-actions{flex-wrap:wrap;justify-content:flex-start}}
</style>
